from selenium import webdriverfrom selenium.webdriver.chrome.options import Optionsfrom selenium.webdriver.common.by import Byfrom selenium.webdriver.support.ui import WebDriverWaitfrom selenium.webdriver.support import expected_conditions as ECimport time# --- CONFIGURATION ---SWITCH_IP = "10.10.10.2"USERNAME = "YOUR_USERNAME"PASSWORD = "YOUR_PASSWORD"  # Leave as "" if no passwordBROWSER_PATH = "/usr/bin/brave"# Construct the URL to bypass the "Sign In" popup automatically# Format: http://admin:password@10.10.0.2/index.htmlAUTH_URL = f"http://{USERNAME}:{PASSWORD}@{SWITCH_IP}/index.html"print("--- MikroTik Switch 260GSP SwOS Reboot Wrapper ---")# --- BROWSER SETUP ---options = Options()options.binary_location = BROWSER_PATHoptions.add_argument("--headless=new") # Change to "--headless=new" for background runoptions.add_argument("--disable-gpu")options.add_argument("--no-sandbox")options.add_argument("--disable-dev-shm-usage")driver = webdriver.Chrome(options=options)wait = WebDriverWait(driver, 20)def force_click(by_type, selector):    """Waits for element and clicks via JavaScript to bypass UI overlays"""    element = wait.until(EC.presence_of_element_located((by_type, selector)))    driver.execute_script("arguments[0].click();", element)    time.sleep(2) # SwOS needs a moment to refresh the content areatry:    print(f"1. Connecting to Switch at {SWITCH_IP}...")    driver.get(AUTH_URL)        # Wait for the main UI to appear    wait.until(EC.presence_of_element_located((By.ID, "tabs")))    print("   Connected successfully.")    print("2. Clicking 'System' Tab...")    # Matches your screenshot: <li id="system"><a href="#system">...</a></li>    force_click(By.CSS_SELECTOR, "#system a")    print("3. Clicking 'Reboot' Button...")    # Matches your screenshot: <a class="btn">Reboot</a>    # We use XPath to ensure we don't click 'Upgrade' by mistake    force_click(By.XPATH, "//a[@class='btn' and text()='Reboot']")    print("4. Handling Confirmation Alert...")    try:        # SwOS triggers a standard browser alert (OK/Cancel)        wait.until(EC.alert_is_present())        alert = driver.switch_to.alert        alert_text = alert.text        print(f"   Alert says: '{alert_text}'")        alert.accept()        print("   Alert accepted. Switch is now rebooting!")    except:        print("   No browser alert appeared. Checking if reboot started...")    print("\nSUCCESS! The Switch has rebooted.")except Exception as e:    print(f"\n--- SCRIPT FAILED ---")    print(f"Error details: {e}")    driver.save_screenshot("swos_debug.png")    print("Check 'swos_debug.png' to see what the browser saw.")finally:    time.sleep(2)    driver.quit()